import{_ as a,o as s,c as n,a2 as i}from"./chunks/framework.CDEKL17z.js";const t="/michi-chat/screenshots/gemma-testcafe.png",k=JSON.parse('{"title":"Model backends","description":"","frontmatter":{},"headers":[],"relativePath":"guide/models.md","filePath":"guide/models.md"}'),l={name:"guide/models.md"};function o(d,e,h,r,p,c){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="model-backends" tabindex="-1">Model backends <a class="header-anchor" href="#model-backends" aria-label="Permalink to &quot;Model backends&quot;">​</a></h1><p>The app never names a real model. It asks LiteLLM for three <strong>aliases</strong>:</p><table tabindex="0"><thead><tr><th>Alias</th><th>Used for</th></tr></thead><tbody><tr><td><code>michi</code></td><td>Chat turns (the bot itself)</td></tr><tr><td><code>judge</code></td><td>Grading eval answers (kept different from <code>michi</code> on purpose)</td></tr><tr><td><code>embed</code></td><td>Knowledge-base embeddings</td></tr></tbody></table><p>What actually serves each alias is decided in <code>litellm.config.yaml</code>. Swapping providers is an edit there - never a code change.</p><h2 id="when-each-model-actually-runs" tabindex="-1">When each model actually runs <a class="header-anchor" href="#when-each-model-actually-runs" aria-label="Permalink to &quot;When each model actually runs&quot;">​</a></h2><p>The three aliases are not a chain; only two of them ever touch a live visitor turn.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LIVE - every visitor message</span></span>
<span class="line"><span>  visitor message</span></span>
<span class="line"><span>     |-- guardrails + daily cap ......... no model (patterns + counters)</span></span>
<span class="line"><span>     |-- answer cache lookup ............ embed</span></span>
<span class="line"><span>     |      hit -&gt; stream cached answer, done (no other model runs)</span></span>
<span class="line"><span>     |      miss v</span></span>
<span class="line"><span>     &#39;-- michi (the chat model, tool loop)</span></span>
<span class="line"><span>            |-- get_weather / get_events / get_menu ... plain HTTP, no model</span></span>
<span class="line"><span>            &#39;-- search_kb -&gt; embed (question -&gt; vector)</span></span>
<span class="line"><span>                              -&gt; Postgres pgvector: nearest chunks (not a model)</span></span>
<span class="line"><span>            v</span></span>
<span class="line"><span>        answer streams to the visitor; embed stores it in the cache</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OFFLINE - only when you run eval:answers</span></span>
<span class="line"><span>  golden questions -&gt; the real pipeline above -&gt; answers -&gt; judge grades each one</span></span></code></pre></div><ul><li><code>michi</code> is the only model that writes words to a visitor.</li><li><code>embed</code> never writes words; it only turns text into vectors (cache check, KB search).</li><li><code>judge</code> runs only in the eval suite - a different model than <code>michi</code>, so the bot never grades its own homework, and it costs nothing per visitor.</li></ul><p>Cheapest turns first: a guardrail refusal uses no model at all, a cache hit uses only <code>embed</code>, and a full tool-loop answer uses <code>michi</code> once per round plus <code>embed</code> twice.</p><h2 id="path-a-local-ollama-default" tabindex="-1">Path A: local Ollama (default) <a class="header-anchor" href="#path-a-local-ollama-default" aria-label="Permalink to &quot;Path A: local Ollama (default)&quot;">​</a></h2><p>On the machine running Docker:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen3.5:4b</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # michi</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:7b</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # judge</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nomic-embed-text</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # embed</span></span></code></pre></div><p>The default config reaches Ollama at <code>host.docker.internal:11434</code>, which works on Docker Desktop and (via the compose file&#39;s <code>extra_hosts</code>) on plain Linux. If Ollama lives elsewhere, set <code>OLLAMA_API_BASE</code> in <code>.env</code>.</p><h2 id="path-b-a-hosted-provider" tabindex="-1">Path B: a hosted provider <a class="header-anchor" href="#path-b-a-hosted-provider" aria-label="Permalink to &quot;Path B: a hosted provider&quot;">​</a></h2><p>Put your key in <code>.env</code> (the compose file passes <code>OPENAI_API_KEY</code> and <code>DASHSCOPE_API_KEY</code> through), then repoint an alias in <code>litellm.config.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">model_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">michi</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  litellm_params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">openai/gpt-4o-mini</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    api_key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">os.environ/OPENAI_API_KEY</span></span></code></pre></div><p>Restart the litellm container after editing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> litellm</span></span></code></pre></div><h2 id="trying-a-different-model-on-one-tenant" tabindex="-1">Trying a different model on one tenant <a class="header-anchor" href="#trying-a-different-model-on-one-tenant" aria-label="Permalink to &quot;Trying a different model on one tenant&quot;">​</a></h2><p>Add a trial alias in the yaml (say, <code>gemma</code> → <code>ollama_chat/gemma3:4b</code>, or the bundled <code>michi-mini</code> → <code>gemma3:1b</code> economy tier), restart the litellm container, and set one tenant&#39;s <strong>Model alias</strong> field to it in the admin UI. That tenant now runs the new model while every other tenant is untouched - A/B testing as configuration. The alias in use is shown to visitors in the chat footer (&quot;AI model: …&quot;).</p><p><img src="`+t+'" alt="A test tenant answering through a trial alias"></p><p>Smaller-model honesty: a ~1B model answers roughly 3x faster than a 4B one, but tool-calling reliability degrades. Before switching a real tenant down a size, run <code>kb:eval</code> and a handful of real tool questions against it.</p><h2 id="the-embedding-caveat" tabindex="-1">The embedding caveat <a class="header-anchor" href="#the-embedding-caveat" aria-label="Permalink to &quot;The embedding caveat&quot;">​</a></h2><p>The knowledge-base column is sized to <strong>768 dimensions</strong> (nomic-embed-text). Changing the <code>embed</code> alias to a model with different dimensions requires a schema migration <strong>and</strong> re-embedding every document. Change <code>michi</code> and <code>judge</code> freely; think twice about <code>embed</code>.</p>',24)])])}const g=a(l,[["render",o]]);export{k as __pageData,g as default};
